//! The symbol and emoji catalogue.
//!
//! Every mark in `assets/glyphs.txt` is one the **bundled faces can actually draw**: the file was
//! generated by walking the cmaps of Noto Emoji, Noto Sans Symbols, Noto Sans Symbols 2 and DejaVu
//! Sans (the fallback chain every family in `theme.rs` ends with) and keeping only the codepoints
//! those fonts carry, inside the symbol and pictograph blocks. A picker that offers a glyph the fonts
//! do not have is a picker that inserts a tofu box, and the app has been bitten by that twice already
//! (`✕` in the find strip, `▏` in the quote gutter).
//!
//! Lines are `HEX|name|aliases|group`. The parse borrows from the `include_str!` slice, so the whole
//! catalogue costs one `Vec` of borrowed slices — no per-glyph allocation, nothing to keep in sync.

/// One mark in the picker.
pub struct Glyph {
    pub ch: char,
    /// The Unicode name, lower-case: `check mark`, `rightwards arrow`, `fire`.
    pub name: &'static str,
    /// Extra words that should find it (`tick check checkmark yes done ok`). Empty for most.
    pub alias: &'static str,
    /// The catalogue key this mark belongs to (`marks`, `arrows`, …).
    pub group: &'static str,
}

/// The groups in the order the picker draws its chips, and the short label each is shown by. The keys
/// are the file's own, so a line whose group is not in this list is a bug the tests catch.
pub const GROUPS: [(&str, &str); 15] = [
    ("smileys", "People"),
    ("nature", "Nature"),
    ("food", "Food"),
    ("travel", "Travel"),
    ("activities", "Sport"),
    ("objects", "Things"),
    ("symbols", "Symbols"),
    ("marks", "Marks"),
    ("arrows", "Arrows"),
    ("maths", "Maths"),
    ("shapes", "Shapes"),
    ("technical", "Keys"),
    ("numbers", "Numbers"),
    ("currency", "Money"),
    ("punct", "Punct"),
];

/// The marks the right-click menu offers without opening the picker: the handful a note actually
/// uses while writing. Their labels come from the catalogue, so the menu says `check mark`, not a
/// second hand-written name that could drift.
pub const QUICK: [char; 16] = [
    '✓', '✗', '→', '←', '↑', '↓', '★', '☆', '•', '–', '—', '±', '°', '⚠', '☐', '☑',
];

static RAW: &str = include_str!("../assets/glyphs.txt");
static ALL: std::sync::OnceLock<Vec<Glyph>> = std::sync::OnceLock::new();

/// The whole catalogue, parsed once.
pub fn all() -> &'static [Glyph] {
    ALL.get_or_init(parse)
}

fn parse() -> Vec<Glyph> {
    let mut out = Vec::new();
    for line in RAW.lines() {
        let mut parts = line.split('|');
        let (Some(hex), Some(name), Some(alias), Some(group)) =
            (parts.next(), parts.next(), parts.next(), parts.next())
        else {
            continue;
        };
        let Ok(cp) = u32::from_str_radix(hex, 16) else {
            continue;
        };
        let Some(ch) = char::from_u32(cp) else {
            continue;
        };
        out.push(Glyph {
            ch,
            name,
            alias,
            group,
        });
    }
    out
}

/// The marks of one group, in catalogue order.
pub fn in_group(key: &str) -> impl Iterator<Item = &'static Glyph> {
    all().iter().filter(move |g| g.group == key)
}

/// How many marks a group holds — the picker shows it on the chip, so a group that is empty or huge is
/// visible before it is opened.
pub fn group_len(key: &str) -> usize {
    all().iter().filter(|g| g.group == key).count()
}

/// The label a group key is drawn by (`marks` → `Marks`).
pub fn group_label(key: &str) -> &'static str {
    GROUPS
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, l)| *l)
        .unwrap_or("More")
}

/// The mark with this character, if the catalogue carries it.
pub fn by_char(ch: char) -> Option<&'static Glyph> {
    all().iter().find(|g| g.ch == ch)
}

/// Search names and aliases. Every word of the query has to appear somewhere in the line, so
/// `arrow right` finds `→` (its name is `rightwards arrow`) and `right arrow` finds it too.
///
/// A query that is a codepoint — `2192` or `u+2192` or `1f525` — finds that exact mark first, which is
/// how the rare symbols are reached without knowing what they are called.
pub fn search(query: &str, limit: usize) -> Vec<&'static Glyph> {
    let q = query.trim().to_lowercase();
    if q.is_empty() || limit == 0 {
        return Vec::new();
    }
    let hex = q.strip_prefix("u+").unwrap_or(&q);
    if let Ok(cp) = u32::from_str_radix(hex, 16) {
        if let Some(ch) = char::from_u32(cp) {
            if let Some(g) = by_char(ch) {
                return vec![g];
            }
        }
    }
    let words: Vec<&str> = q.split_whitespace().collect();
    // Rank, do not merely filter: `arrow right` matches fifty marks by name (`rightwards arrow with
    // hook`, `two headed arrow with tail`…), and the one the user means is the short one whose name
    // reads like their words. Score, then the shorter name, then the character, so the list is the
    // same on every run.
    let mut scored: Vec<(u8, usize, &'static Glyph)> = Vec::new();
    for g in all() {
        let hay = if g.alias.is_empty() {
            g.name.to_string()
        } else {
            format!("{} {}", g.name, g.alias)
        };
        if !words.iter().all(|w| hay.contains(w)) {
            continue;
        }
        let score = if g.name == q {
            0
        } else if g.name.starts_with(&q) {
            1
        } else if words.iter().all(|w| g.name.contains(w)) {
            2
        } else {
            // only the alias had the words: still a hit, but after the names that really say it
            3
        };
        scored.push((score, g.name.len(), g));
    }
    scored.sort_by_key(|(score, len, g)| (*score, *len, g.ch as u32));
    scored
        .into_iter()
        .take(limit)
        .map(|(_, _, g)| g)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The whole point of the generated file: the app can only offer what the fonts can draw, and the
    /// generation step is the only thing that knows that. A catalogue that quietly shrank (a bad
    /// merge, a regenerated file without the cmap filter) would still pass "not empty", so the floor
    /// is a real number.
    #[test]
    fn the_catalogue_is_the_expected_size() {
        let n = all().len();
        assert!(n > 3000, "only {n} marks in the catalogue");
        assert!(n < 6000, "{n} marks — the file has grown past the symbol and picture blocks");
        for g in all() {
            assert!(!g.name.is_empty(), "a mark with no name: {:?}", g.ch);
            assert!(
                GROUPS.iter().any(|(k, _)| *k == g.group),
                "{} belongs to {:?}, which has no chip",
                g.ch,
                g.group
            );
        }
    }

    /// The marks a note is actually written with have to be there, in the group they are expected in.
    #[test]
    fn the_everyday_marks_are_found_by_the_words_people_use() {
        for (q, want) in [
            ("tick", '✓'),
            ("check mark", '✓'),
            ("arrow right", '→'),
            ("right arrow", '→'),
            ("star", '★'),
            ("warning", '⚠'),
            ("bullet", '•'),
            ("degree", '°'),
            ("euro", '€'),
            ("fire", '🔥'),
            ("brain", '🧠'),
        ] {
            let hits = search(q, 40);
            assert!(
                hits.iter().any(|g| g.ch == want),
                "{q:?} did not find {want}: {:?}",
                hits.iter().map(|g| g.ch).collect::<String>()
            );
        }
        // and a codepoint reaches a mark nothing would name in words
        assert_eq!(search("2192", 1)[0].ch, '→');
        assert_eq!(search("u+1F525", 1)[0].ch, '🔥');
    }

    #[test]
    fn every_quick_mark_is_in_the_catalogue() {
        for ch in QUICK {
            assert!(by_char(ch).is_some(), "{ch} is offered by the menu but is not in the catalogue");
        }
    }
}
